/**
 * react-i18next configuration.
 *
 * Interface languages: English, Hindi, and the eight Indian languages Sarvam's
 * Bulbul voice can also speak. Screen text and audio therefore cover the same
 * set, so choosing a language never leaves the patient reading one language and
 * hearing another.
 *
 * English and Hindi are hand-written. The rest were generated by
 * `backend/scripts/generate_locales.py` from the English source and are marked
 * `"reviewed": "no"` in their own `_meta` block — machine translation is a real
 * improvement on showing a patient English they cannot read, but it is not a
 * substitute for review by someone who speaks the language.
 *
 * Adding a language: run the generator, drop the file in, and add it here plus
 * to `_UI_TRANSLATED` in `backend/app/interview/languages.py`. Odia (od) is the
 * one gap in Bulbul's set — its generation ran out of Sarvam credits.
 */

import i18n from "i18next";
import { initReactI18next } from "react-i18next";

import bnTranslation from "./locales/bn/translation.json";
import enTranslation from "./locales/en/translation.json";
import guTranslation from "./locales/gu/translation.json";
import hiTranslation from "./locales/hi/translation.json";
import knTranslation from "./locales/kn/translation.json";
import mlTranslation from "./locales/ml/translation.json";
import mrTranslation from "./locales/mr/translation.json";
import paTranslation from "./locales/pa/translation.json";
import taTranslation from "./locales/ta/translation.json";
import teTranslation from "./locales/te/translation.json";

export const SUPPORTED_LANGUAGES = [
  "en",
  "hi",
  "bn",
  "mr",
  "te",
  "ta",
  "gu",
  "kn",
  "ml",
  "pa",
] as const;
export type SupportedLanguage = (typeof SUPPORTED_LANGUAGES)[number];

/**
 * The language the patient already chose this visit, if any.
 *
 * Read directly rather than via the language store, because that module imports
 * this one — and i18next needs the value at init time, before either is wired up.
 */
function storedLanguage(): SupportedLanguage | null {
  if (typeof sessionStorage === "undefined") return null;
  const stored = sessionStorage.getItem("medikiosk_language");
  return stored && (SUPPORTED_LANGUAGES as readonly string[]).includes(stored)
    ? (stored as SupportedLanguage)
    : null;
}

i18n.use(initReactI18next).init({
  resources: {
    en: { translation: enTranslation },
    hi: { translation: hiTranslation },
    bn: { translation: bnTranslation },
    mr: { translation: mrTranslation },
    te: { translation: teTranslation },
    ta: { translation: taTranslation },
    gu: { translation: guTranslation },
    kn: { translation: knTranslation },
    ml: { translation: mlTranslation },
    pa: { translation: paTranslation },
  },
  // Restore the patient's choice before first paint. Without this a refresh
  // mid-visit drops them back to English with no explanation, which for a
  // patient who reads only Tamil means the kiosk becomes unusable.
  lng: storedLanguage() ?? import.meta.env.VITE_DEFAULT_LOCALE ?? "en",
  fallbackLng: "en",
  interpolation: {
    escapeValue: false, // React already escapes by default
  },
  // Avoid XSS: never parse HTML in translation strings
  parseMissingKeyHandler: (key) => `[${key}]`,
});

export default i18n;
